def proverb(*rhyme_items, qualifier):
    print(rhyme_items)
    if not rhyme_items:
        return []
    phrases = [f'For want of a {element_1} the {element_2} was lost.'
               for element_1, element_2 in zip(rhyme_items, rhyme_items[1:])]
    if qualifier:
        phrases.append(f'And all for the want of a {qualifier} {rhyme_items[0]}.')
    else:
        phrases.append(f'And all for the want of a {rhyme_items[0]}.')
    return phrases

from math import sqrt, ceil, gcd


def triplets_in_range(start, end):
    for limit in range(4, end + 1, 4):
        for x_pos, y_pos, z_pos in primitive_triplets(limit):
            alpha = x_pos
            beta = y_pos
            gamma = z_pos

            while alpha < start:
                alpha = alpha + x_pos
                beta = beta + y_pos
                gamma = gamma + z_pos

            while gamma <= end:
                yield [alpha, beta, gamma]

                alpha = alpha + x_pos
                beta = beta + y_pos
                gamma = gamma + z_pos


def euclidian_coprimes(limit):
    mean = limit // 2
    for idx in range(1, int(ceil(sqrt(mean)))):
        if mean % idx == 0:
            member = mean // idx
            if (member - idx) % 2 == 1 and gcd(member, idx) == 1:
                yield member, idx


def primitive_triplets(limit):
    """See Euclid's formula
    (https://en.wikipedia.org/wiki/Pythagorean_triple#Generating_a_triple)
    for more information
    """
    for member_1, member_2 in euclidian_coprimes(limit):
        calc_1 = member_1 ** 2
        calc_2 = member_2 ** 2

        alpha = calc_1 - calc_2
        beta = 2 * member_1 * member_2
        gamma = calc_1 + calc_2

        if alpha > beta:
            alpha, beta = beta, alpha

        yield alpha, beta, gamma


def triplets_with_sum(number):
    return [
        triplet for triplet
        in triplets_in_range(1, number // 2)
        if sum(triplet) == number
        ]

class Queen:
    def __init__(self, row, column):
        if row < 0:
            raise ValueError('row not positive')
        if not 0 <= row <= 7:
            raise ValueError('row not on board')
        if column < 0:
            raise ValueError('column not positive')
        if not 0 <= column <= 7:
            raise ValueError('column not on board')
        self.row = row
        self.column = column

    def can_attack(self, another_queen):
        idx = abs(self.row - another_queen.row)
        edx = abs(self.column - another_queen.column)
        if idx == edx == 0:
            raise ValueError('Invalid queen position: both queens in the same square')
        elif idx == edx or idx == 0 or edx == 0:
            return True
        else:
            return False

from itertools import cycle, chain


def fence_pattern(rails, size):
    zig_zag = cycle(chain(range(rails), range(rails - 2, 0, -1)))
    return zip(zig_zag, range(size))


def encode(msg, rails):
    fence = fence_pattern(rails, len(msg))
    return ''.join(msg[idx] for _, idx in sorted(fence))


def decode(msg, rails):
    fence = fence_pattern(rails, len(msg))
    fence_msg = zip(msg, sorted(fence))
    return ''.join(char for char, _ in sorted(fence_msg, key=lambda item: item[1][1]))

def convert(number):
    """
    Converts a number to a string according to the raindrop sounds.
    """

    result = ''
    if number % 3 == 0:
        result += 'Pling'
    if number % 5 == 0:
        result += 'Plang'
    if number % 7 == 0:
        result += 'Plong'

    if not result:
        result = str(number)
    return result

from math import gcd


class Rational:
    def __init__(self, numer, denom):
        # abs used for backward compatibility with fractions.gcd
        gcd_num = abs(gcd(numer, denom))

        self.numer = numer // gcd_num
        self.denom = denom // gcd_num

        if self.denom < 0:
            self.numer *= -1
            self.denom *= -1

    def __eq__(self, other):
        return self.numer == other.numer and self.denom == other.denom

    def __repr__(self):
        return f'{self.numer}/{self.denom}'

    def __add__(self, other):
        numer = (self.numer * other.denom) + (other.numer * self.denom)
        return Rational(numer, other.denom * self.denom)

    def __sub__(self, other):
        return self + (-other)

    def __mul__(self, other):
        return Rational(self.numer * other.numer, self.denom * other.denom)

    def __truediv__(self, other):
        return Rational(self.numer * other.denom, self.denom * other.numer)

    def __abs__(self):
        return Rational(abs(self.numer), self.denom)

    def __pow__(self, power):
        if power < 0:
            return Rational(pow(self.denom, -power), pow(self.numer, -power))

        else:
            return Rational(pow(self.numer, power), pow(self.denom, power))

    def __rpow__(self, base):
        return base ** (self.numer / self.denom)

    def __neg__(self):
        return Rational(self.numer * (-1), self.denom)

class Cell:
    def __init__(self):
        self._watchers = []
        self._value = None
        self.counter = 0

    def add_watcher(self, cell):
        self._watchers.append(cell)

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        self.counter += 1
        for cell in self._watchers:
            cell.compute()


class InputCell(Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self.inputs = inputs
        self.func = compute_function
        self.callbacks = set()
        self.compute()
        self._register_inputs()

    def _register_inputs(self):
        for inp in self.inputs:
            inp.add_watcher(self)

    def compute(self):
        # Only compute this cell when all inputs have same counters
        if len({inp.counter for inp in self.inputs}) > 1:
            return
        new_val = self.func([inp.value for inp in self.inputs])
        if new_val != self._value:
            self.value = new_val
            for cb in self.callbacks:
                cb(new_val)

    def add_callback(self, callback):
        self.callbacks.add(callback)

    def remove_callback(self, callback):
        if callback in self.callbacks:
            self.callbacks.remove(callback)

import itertools


class Corners:
    def __init__(self, idx, jdx):
        # i, j are position of corner
        self.idx = idx
        self.jdx = jdx

    def __str__(self):
        return '[' + str(self.idx) + ', ' + str(self.jdx) + ']'


# return corner on the same line
def same_line(index, list_obj):
    for corner in list_obj:
        if corner.idx == index:
            return corner
    return None


# return corner on the same column
def same_col(index, list_obj):
    for corner in list_obj:
        if corner.jdx == index:
            return corner
    return None


def search_corners(list_obj):

    return [Corners(item, element) for item in range(len(list_obj))
            for element in range(len(list_obj[item]))
            if list_obj[item][element] == '+']


# validate that 4 points form a rectangle by
# comparing distance to centroid of the rectangle for all corners
def possible_rect(quartet):
    mid_x = 0
    mid_y = 0

    for centroid in quartet:
        mid_x = mid_x + centroid.idx / 4.0
        mid_y = mid_y + centroid.jdx / 4.0

    # reference distance using first corner
    dx = abs(quartet[0].idx - mid_x)
    dy = abs(quartet[0].jdx - mid_y)

    # Check all the same distance from centroid are equals
    for idx in range(1, len(quartet)):
        if abs(quartet[idx].idx - mid_x) != dx or abs(quartet[idx].jdx - mid_y) != dy:
            return False
    return True


# validate path between two corners
def path(corner1, corner2, item):
    if corner1.idx == corner2.idx:
        for jdx in range(min(corner1.jdx + 1, corner2.jdx + 1),
                       max(corner1.jdx, corner2.jdx)):
            if item[corner1.idx][jdx] != '-' and item[corner1.idx][jdx] != '+':
                return False
        return True

    elif corner1.jdx == corner2.jdx:
        for idx in range(min(corner1.idx + 1, corner2.idx + 1),
                       max(corner1.idx, corner2.idx)):
            if item[idx][corner1.jdx] != '|' and item[idx][corner1.jdx] != '+':
                return False
        return True
    return None


# validate path of rectangle
def validate_rect(rectangle, item):
    # validate connection at every corner
    # with neighbours on the same line and col
    for idx, _ in enumerate(rectangle):
        line = same_line(rectangle[idx].idx, rectangle[0:idx] + rectangle[idx + 1:])
        column = same_col(rectangle[idx].jdx, rectangle[0:idx] + rectangle[idx + 1:])

        if not path(rectangle[idx], line, item) or not path(rectangle[idx], column, item):
            return False

    return True


# count number of rectangles inside ASCII in input lines
def rectangles(strings=''):
    rectangle_total = 0
    # test empty str
    if not strings:
        return rectangle_total

    corners = search_corners(strings)

    # no corners in str
    if not corners:
        return rectangle_total

    # all combinations of 4 corners
    quartets = list(itertools.combinations(corners, r=4))
    paths = (quartet for quartet in quartets if possible_rect(quartet))

    # validate paths
    for idx in paths:
        if validate_rect(idx, strings):
            rectangle_total += 1
    return rectangle_total

import collections
import itertools

class RelativeDistance:
    def __init__(self, family_tree):
        self.neighbors = collections.defaultdict(set)
        for parent, children in family_tree.items():
            for child in children:
                self.neighbors[parent].add(child)
                self.neighbors[child].add(parent)

            for child1, child2 in itertools.combinations(children, 2):
                self.neighbors[child1].add(child2)
                self.neighbors[child2].add(child1)

    def degree_of_separation(self, person_a, person_b):
        if person_a not in self.neighbors:
            raise ValueError("Person A not in family tree.")
        if person_b not in self.neighbors:
            raise ValueError("Person B not in family tree.")

        queue = collections.deque([(person_a, 0)])
        visited = {person_a}

        while queue:
            current, degree = queue.popleft()

            if current == person_b:
                return degree

            for neighbor in self.neighbors.get(current, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, degree + 1))

        raise ValueError("No connection between person A and person B.")

import json


class RestAPI:
    def __init__(self, database=None):
        self.database = database or {'users': []}

    def update(self):
        for user in self.database['users']:
            owed_by = user['owed_by']
            owes = user['owes']
            for debtor in list(owed_by.keys()):
                if debtor in owes:
                    diff = 0
                    if debtor in owes:
                        diff = owes[debtor]
                        del owes[debtor]
                    if debtor in owed_by:
                        diff -= owed_by[debtor]
                        del owed_by[debtor]
                    if diff > 0:
                        owes[debtor] = diff
                    elif diff < 0:
                        owed_by[debtor] = -diff
            user['balance'] = sum(owed_by.values()) - sum(owes.values())

    def get(self, url, payload=None):
        if payload is not None:
            payload = json.loads(payload)
        if url == '/users':
            if payload is None:
                return json.dumps(self.database)
            else:
                return json.dumps({
                    'users': [
                        user for user in self.database['users']
                        if user['name'] in payload['users']
                    ]
                })
        return None

    def post(self, url, payload=None):
        result = None
        if payload is not None:
            payload = json.loads(payload)
        if url == '/add':
            if payload is not None:
                name = payload['user']
                users = self.database['users']
                user = None
                for idx in users:
                    if idx['name'] == name:
                        user = idx
                        break
                if user is None:
                    new_user = {
                        'name': name,
                        'owes': {},
                        'owed_by': {},
                        'balance': 0
                    }
                    users.append(new_user)
                    self.update()
                    result = json.dumps(new_user)
        elif url == '/iou':
            if payload is not None:
                lender_name = payload['lender']
                borrower_name = payload['borrower']
                amount = payload['amount']
                lender = borrower = None
                for user in self.database['users']:
                    if user['name'] == lender_name:
                        lender = user
                    elif user['name'] == borrower_name:
                        borrower = user
                if lender is not None and borrower is not None:
                    lender['owed_by'].setdefault(borrower_name, 0)
                    lender['owed_by'][borrower_name] += amount
                    borrower['owes'].setdefault(lender_name, 0)
                    borrower['owes'][lender_name] += amount
                    self.update()
                    result = self.get(
                        '/users',
                        json.dumps({'users': [lender_name, borrower_name]})
                    )
        return result

