import random

ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
class Robot:
    def __init__(self):
        self._name = None
        self._past_names = set()

    def prefix(self):
        return ''.join([
            random.choice(ALPHABET)
            for _ in range(0, 2)
        ])

    def suffix(self):
        return ''.join([
            str(random.choice(range(0, 10)))
            for _ in range(0, 3)
        ])

    def get_name(self):
        if not self._name:

            # Collision detection
            while True:
                self._name = self.prefix() + self.suffix()
                if self._name not in self._past_names:
                    self._past_names.add(self._name)
                    break

        return self._name

    def del_name(self):
        self._name = None

    name = property(get_name, None, del_name)

    def reset(self):
        del self.name

NORTH, EAST, SOUTH, WEST = range(4)


class Compass:
    compass = [NORTH, EAST, SOUTH, WEST]

    def __init__(self, direction=NORTH):
        self.direction = direction

    def left(self):
        self.direction = self.compass[self.direction - 1]

    def right(self):
        self.direction = self.compass[(self.direction + 1) % 4]


class Robot:
    def __init__(self, direction=NORTH, x_pos=0, y_pos=0):
        self.compass = Compass(direction)
        self.x_pos = x_pos
        self.y_pos = y_pos

    def advance(self):
        if self.direction == NORTH:
            self.y_pos += 1
        elif self.direction == SOUTH:
            self.y_pos -= 1
        elif self.direction == EAST:
            self.x_pos += 1
        elif self.direction == WEST:
            self.x_pos -= 1

    def turn_left(self):
        self.compass.left()

    def turn_right(self):
        self.compass.right()

    def move(self, commands):
        instructions = {'A': self.advance,
                        'R': self.turn_right,
                        'L': self.turn_left}
        for cmd in commands:
            if cmd in instructions:
                instructions[cmd]()

    @property
    def direction(self):
        return self.compass.direction

    @property
    def coordinates(self):
        return (self.x_pos, self.y_pos)

from string import ascii_lowercase, ascii_uppercase


ALPHA_LEN = len(ascii_lowercase)


def rotate(message, key):
    coded_message = ''
    for char in message:
        if char in ascii_lowercase:
            char = ascii_lowercase[(ascii_lowercase.index(char) + key) % ALPHA_LEN]
        elif char in ascii_uppercase:
            char = ascii_uppercase[(ascii_uppercase.index(char) + key) % ALPHA_LEN]
        coded_message += char
    return coded_message

from itertools import groupby
from re import sub


def decode(string):
    return sub(r'(\d+)(\D)', lambda main: main.group(2) * int(main.group(1)), string)


def encode(string):
    def single_helper(key, group):
        size = len(list(group))
        return key if size == 1 else str(size) + key
    return ''.join(single_helper(key, group) for key, group in groupby(string))

def saddle_points(matrix):
    if not matrix:
        return []

    if any(len(row) != len(matrix[0]) for row in matrix):
        raise ValueError('irregular matrix')

    mmax = [max(row) for row in matrix]
    mmin = [min(col) for col in zip(*matrix)]

    points = [{'row': index + 1, 'column': col_index + 1}
              for index, _ in enumerate(matrix)
              for col_index, _ in enumerate(matrix[0])
              if mmax[index] == mmin[col_index]]

    return points or []

def tree_from_traversals(preorder, inorder):
    if len(preorder) != len(inorder):
        raise ValueError('traversals must have the same length')
    if set(preorder) != set(inorder):
        raise ValueError('traversals must have the same elements')
    if len(set(preorder)) != len(preorder) != len(set(inorder)):
        raise ValueError('traversals must contain unique items')
    if not preorder:
        return {}

    value = preorder.pop(0)
    index = inorder.index(value)
    left_inorder, right_inorder = inorder[:index], inorder[index+1:]

    left_preorder = [idx for idx in preorder if idx in left_inorder]
    right_preorder = [idx for idx in preorder if idx in right_inorder]

    left = tree_from_traversals(left_preorder, left_inorder)
    right = tree_from_traversals(right_preorder, right_inorder)

    return {'v': value, 'l': left, 'r': right}

def say(number):
    small = dict(enumerate((
            'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight',
            'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen',
            'sixteen', 'seventeen', 'eighteen', 'nineteen')))

    tens = {20: 'twenty', 30: 'thirty', 40: 'forty', 50: 'fifty',
            60: 'sixty', 70: 'seventy', 80: 'eighty', 90: 'ninety'}

    kilo = 1e3
    mega = 1e6
    giga = 1e9
    tera = 1e12

    if number < 0:
        raise ValueError('input out of range')
    if number >= tera:
        raise ValueError('input out of range')

    if number < 20:
        return small[number]

    if number < 100:
        if number % 10 == 0:
            return tens[number]
        return tens[number // 10 * 10] + '-' + small[number % 10]

    if number < kilo:
        if number % 100 == 0:
            return small[number // 100] + ' hundred'
        return small[number // 100] + ' hundred ' + say(number % 100)

    if number < mega:
        if number % kilo == 0:
            return say(number // kilo) + ' thousand'
        return say(number // kilo) + ' thousand ' + say(number % kilo)

    if number < giga:
        if number % mega == 0:
            return say(number // mega) + ' million'
        return say(number // mega) + ' million ' + say(number % mega)

    if number % giga == 0:
        return say(number // giga) + ' billion'
    return say(number // giga) + ' billion ' + say(number % giga)

class Scale:
    ASCENDING_INTERVALS = ['m', 'M', 'A']
    CHROMATIC_SCALE = ['A', 'A#', 'B', 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#']
    FLAT_CHROMATIC_SCALE = ['A', 'Bb', 'B', 'C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab']
    FLAT_KEYS = ['F', 'Bb', 'Eb', 'Ab', 'Db', 'Gb', 'd', 'g', 'c', 'f', 'bb', 'eb']

    def __init__(self, tonic, intervals=None):
        self.tonic = tonic.capitalize()
        self.intervals = intervals
        self.chromatic_scale = (self.FLAT_CHROMATIC_SCALE if tonic in self.FLAT_KEYS else self.CHROMATIC_SCALE)

    def chromatic(self):
        return self._reorder_chromatic_scale()

    def interval(self, intervals):
        last_index = 0
        pitches = []
        scale = self._reorder_chromatic_scale()

        for _, interval in enumerate(intervals):
            pitches.append(scale[last_index])
            last_index += self.ASCENDING_INTERVALS.index(interval) + 1

        pitches.append(self.tonic)

        return pitches

    def _reorder_chromatic_scale(self):
        index = self.chromatic_scale.index(self.tonic)
        return  self.chromatic_scale[index:] + self.chromatic_scale[:index]

POINTS = {
    'a': 1, 'b': 3, 'c': 3, 'd': 2, 'e': 1,
    'f': 4, 'g': 2, 'h': 4, 'i': 1, 'j': 8,
    'k': 5, 'l': 1, 'm': 3, 'n': 1, 'o': 1,
    'p': 3, 'q': 10, 'r': 1, 's': 1, 't': 1,
    'u': 1, 'v': 4, 'w': 4, 'x': 8, 'y': 4,
    'z': 10
}


def score(word):
    if not word.isalpha():
        return 0
    return sum(POINTS[letter] for letter in word.lower())

def slices(series, length):
    if not series:
        raise ValueError('series cannot be empty')
    elif length == 0:
        raise ValueError('slice length cannot be zero')
    elif length < 0:
        raise ValueError('slice length cannot be negative')
    elif len(series) < length:
        raise ValueError('slice length cannot be greater than series length')

    return [series[idx:idx + length] for idx in range(len(series) - length + 1)]

"""Parse an SGF tree."""
from __future__ import annotations

import collections
import dataclasses
import string


@dataclasses.dataclass
class SgfTree:
    """SGF Node."""

    properties: dict[str, str] = dataclasses.field(default_factory=dict)
    children: list[SgfTree] = dataclasses.field(default_factory=list)


def parse_property_vals(sgf: str, idx: int) -> tuple[int, list[str]]:
    """Parse property values, returning the next index and values."""
    values = []
    while idx < len(sgf):
        if sgf[idx] != "[":
            break

        # Start of the value.
        idx += 1
        prop_val = ""
        while sgf[idx] != "]":
            # \ has special SGF handling.
            if sgf[idx] == "\\":
                if sgf[idx:idx + 2] == "\\\n":
                    # Newlines are removed if they come immediately after a \,
                    # otherwise they remain as newlines.
                    pass
                else:
                    # \ is the escape character. Any non-whitespace character
                    # after \ is inserted as-is
                    prop_val += sgf[idx + 1]
                idx += 2
            else:
                prop_val += sgf[idx]
                idx += 1

        # All whitespace characters other than newline are converted to spaces.
        for char in string.whitespace:
            if char == "\n":
                continue
            prop_val = prop_val.replace(char, " ")

        values.append(prop_val)
        idx += 1

    return idx, values


def parse_node(sgf: str) -> SgfTree:
    """Parse and return a Node."""
    if not sgf.startswith(";"):
        raise ValueError("node must start with ';'")

    idx = 1
    prop_key_start = idx

    properties = collections.defaultdict(list)
    children = []

    while idx < len(sgf):
        if sgf[idx] == "[":
            # Parse property values.
            if idx == prop_key_start:
                raise ValueError("propery key is empty")
            prop_key = sgf[prop_key_start:idx]
            if not prop_key.isupper():
                raise ValueError('property must be in uppercase')

            idx, prop_vals = parse_property_vals(sgf, idx)
            properties[prop_key].extend(prop_vals)

            # New property.
            prop_key_start = idx
        elif sgf[idx] == ";":
            # Single child.
            child = parse_node(sgf[idx:])
            children.append(child)
            break
        elif sgf[idx] == "(":
            # Multiple children.
            children = []
            while idx < len(sgf):
                if sgf[idx] != "(":
                    break
                # Child start.
                idx += 1
                child_start = idx
                while sgf[idx] != ")":
                    idx += 1
                # Child end.
                child = parse_node(sgf[child_start:idx])
                children.append(child)
                idx += 1
        else:
            idx += 1

    if idx > prop_key_start and not properties:
        raise ValueError('properties without delimiter')
    return SgfTree(children=children, properties=dict(properties))


def parse(sgf: str) -> SgfTree:
    """Parse an SGF tree."""
    if not sgf.startswith("(") and not sgf.endswith(")"):
        raise ValueError('tree missing')
    if not sgf.startswith("(;"):
        raise ValueError('tree with no nodes')
    inside = sgf[1:-1]
    return parse_node(inside)

def primes(limit):
    prime = [True] * (limit + 1)
    prime[0] = prime[1] = False
    for idx in range(2, int(limit ** 0.5) + 1):
        if prime[idx]:
            for edx in range(idx * idx, limit + 1, idx):
                prime[edx] = False

    return [edx for edx, idx in enumerate(prime) if idx]

