def gamestate(board):
    def check_if_won(player):
        # Rows
        for row in board:
            if all(cell == player for cell in row):
                return True

        # Cols
        for col in range(3):
            if all(board[row][col] == player for row in range(3)):
                return True

        # top left to bottom right
        if all(board[i][i] == player for i in range(3)):
            return True

        # top right to bottom left
        if all(board[i][2-i] == player for i in range(3)):
            return True
        return False

    x_count = sum(row.count("X") for row in board)
    o_count = sum(row.count("O") for row in board)

    if o_count > x_count:
        raise ValueError("Wrong turn order: O started")
    if x_count > o_count + 1:
        raise ValueError("Wrong turn order: X went twice")

    x_won = check_if_won("X")
    o_won = check_if_won("O")

    if x_won and o_won:
        raise ValueError("Impossible board: game should have ended after the game was won")

    if x_won:
        if x_count == o_count:
            raise ValueError("Impossible board: game should have ended after the game was won")
        return "win"

    if o_won:
        if x_count > o_count:
            raise ValueError("Impossible board: game should have ended after the game was won")
        return "win"

    if x_count + o_count == 9:
        return "draw"

    return "ongoing"

def keep(sequence, predicate):
    return [element for element in sequence if predicate(element)]

def discard(sequence, predicate):
    return [element for element in sequence if not predicate(element)]

SUBLIST = 0
SUPERLIST = 1
EQUAL = 2
UNEQUAL = 3


def sublist(list_one, list_two):
    if list_one == list_two:
        return EQUAL
    if contains(list_one, list_two):
        return SUPERLIST
    if contains(list_two, list_one):
        return SUBLIST
    return UNEQUAL


def contains(list_one, list_two):
    if not list_two:
        return True
    if len(list_two) > len(list_one):
        return False
    for idx in range(len(list_one) - len(list_two) + 1):
        if list_one[idx] != list_two[0]:
            continue
        for edx, _ in enumerate(list_two):
            if list_one[idx + edx] != list_two[edx]:
                break
        else:
            return True
    return False

def sum_of_multiples(limit, multiples):
    return sum(value for value in range(limit)
               if any(value % multiple == 0
                      for multiple in multiples
                      if multiple > 0))

from datetime import datetime, timedelta


def delivery_date(start, description):
    start_date = datetime.fromisoformat(start)


    if  description == 'NOW':
        due_date = start_date + timedelta(hours=2)

    if  description == 'ASAP':
        if str(start_date.time()) < '13:00:00':
            due_date = start_date.replace(hour=17, minute=0)
        else:
            due_date = (
                    start_date.replace(hour=13, minute=0) +
                    timedelta(days=1)
            )

    if description =='EOW':
        if start_date.isoweekday() < 4:
          due_date = (
              start_date.replace(hour=17, minute=0) +
              timedelta(days=5 - start_date.isoweekday())
          )
        else:
          due_date = (
              start_date.replace(hour=20, minute=0) +
              timedelta(days=7 - start_date.isoweekday())
          )

    if description.endswith('M'):
        month = int(description[:-1])
        target = datetime(start_date.year, month, 1, 8, 0, 0)

        if start_date.month >= target.month:
            target = target.replace(year=target.year + 1)
        if target.isoweekday() not in (6,7) and target.day in range(1, 8):
            due_date = target
        else:
            if target.isoweekday() == 6: due_date = target + timedelta(days = 2)
            if target.isoweekday() == 7: due_date = target + timedelta(days = 1)

    if description.startswith('Q'):
        target = int(description[1:])
        current  = ((start_date.month + 2) // 3)
        month =  {"Q1":4,"Q2": 7,"Q3": 10,"Q4": 1}[description]
        rollover = 1 if (current > target or target == 4) else 0

        due_date = start_date.replace(
            start_date.year + rollover, month, 1, 8, 0, 0
        ) - timedelta(days=1)

        if due_date.isoweekday() == 6: due_date -= timedelta(days=1)
        if due_date.isoweekday() == 7: due_date  -= timedelta(days=2)

    return due_date.isoformat()

from collections import defaultdict

RESULTS = dict(win=0, draw=1, loss=2)


def invert_result(result):
    if result == 0:
        return 2
    elif result == 2:
        return 0
    return result


def parse_game(game_line):
    game = game_line.split(';')
    if len(game) == 3 and game[2] in RESULTS:
        result = RESULTS[game[2]]
        return (game[0], result), (game[1], invert_result(result))
    return []


def calculate_points(stats):
    return stats[0] * 3 + stats[1]


def format_table(results):
    table = ['Team                           | MP |  W |  D |  L |  P']

    for team, games in sorted(
            results.items(), key=lambda group: (-calculate_points(group[1]), group[0])):
        team_fmt = '{0:30} | {1:2} | {3:2} | {4:2} | {5:2} | {2:2}'
        table.append(
            team_fmt.format(team, sum(games), calculate_points(games), *games))
    return table


def tally(data):
    table = defaultdict(lambda: [0, 0, 0])

    for line in data:
        for team, result in parse_game(line):
            table[team][result] += 1

    return format_table(table)

def transpose(lines):
    rows = [row.replace(' ', '_') for row in lines.splitlines()]
    rows = [row.ljust(len(max(rows, key=len))) for row in rows]
    rows = [''.join(row) for row in zip(*rows)]
    rows = [row.rstrip().replace('_', ' ') for row in rows]
    return '\n'.join(rows)

class Record:
    def __init__(self, record_id, parent_id):
        self.record_id = record_id
        self.parent_id = parent_id

    def equal_id(self):
        return self.record_id == self.parent_id


class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.children = []


def validate_record(record):
    if record.equal_id() and record.record_id != 0:
        raise ValueError('Only root should have equal record and parent id.')

    if not record.equal_id() and record.parent_id >= record.record_id:
        raise ValueError("Node parent_id should be smaller than its record_id.")


def BuildTree(records):
    parent_dict = {}
    node_dict = {}
    ordered_id = sorted(idx.record_id for idx in records)

    for record in records:
        validate_record(record)
        parent_dict[record.record_id] = record.parent_id
        node_dict[record.record_id] = Node(record.record_id)

    root_id = 0
    root = None

    for index, record_id in enumerate(ordered_id):
        if index != record_id:
            raise ValueError('Record id is invalid or out of order.')

        if record_id == root_id:
            root = node_dict[record_id]
        else:
            parent_id = parent_dict[record_id]
            node_dict[parent_id].children.append(node_dict[record_id])

    return root

def valid(sides):
    return sum(sorted(sides)[:2]) >= sorted(sides)[2] and all(
        side > 0 for side in sides
    )


def equilateral(sides):
    return valid(sides) and all(sides[0] == side for side in sides)


def isosceles(sides):
    return valid(sides) and any(
        side_1 == side_2 for side_1, side_2 in zip(sorted(sides), sorted(sides)[1:])
    )


def scalene(sides):
    return valid(sides) and not isosceles(sides)

